let catX = 50;
let catY = 150;
let catSpeed = 3;

function setup() {
  createCanvas(400, 400);
}

function draw() {
  background(255, 255, 255);

  // ねこを右に動かす
  catX = catX + catSpeed;

  // 画面の端に達したら左端に戻す
  if (catX > 350) {
    catX = 50;
  }

  fill(0, 0, 0); // 黒色
  noStroke();
  ellipse(catX, catY, 30, 40); // ねこを円で表現
}
```

