let buttonX = 100;
let buttonY = 100;
let buttonColor = color(255, 0, 0);
let isRed = true;

function setup() {
  createCanvas(400, 400);
}

function draw() {
  background(255);

  // ボタンの描画
  fill(buttonColor);
  rect(buttonX, buttonY, 100, 100);

  // ボタンの色を切り替えるためのロジック（ここではマウスのクリックで切り替える例として実装）
  if (mouseIsPressed) {
    isRed = !isRed;
    if (isRed) {
      buttonColor = color(255, 0, 0); // 赤
    } else {
      buttonColor = color(0, 0, 255); // 青
    }
  }
}
```
